using Microsoft.AspNetCore.Mvc;
using Sigov.Api.Middlewares;
using Sigov.Application.Common;
using Sigov.Application.Saude;
using Sigov.Domain.Common;

namespace Sigov.Api.Controllers;

[ApiController]
[RequireModule(SaudePermissoes.Modulo)]
[Produces("application/json")]
public abstract class SaudeApiControllerBase : ControllerBase
{
    protected ActionResult<ApiResponse<T>> FromResult<T>(Result<T> result)
    {
        if (result.IsSuccess) return Ok(ApiResponse<T>.Ok(result.Value!));
        var error = result.Error ?? "Falha na operação.";
        return error.Contains("permiss", StringComparison.OrdinalIgnoreCase) || error.Contains("403", StringComparison.OrdinalIgnoreCase) ? StatusCode(StatusCodes.Status403Forbidden, ApiResponse<T>.Fail(error)) : BadRequest(ApiResponse<T>.Fail(error));
    }
    protected ActionResult<ApiResponse<object>> FromResult(Result result)
    {
        if (result.IsSuccess) return Ok(ApiResponse<object>.Ok(new { }));
        var error = result.Error ?? "Falha na operação.";
        return error.Contains("permiss", StringComparison.OrdinalIgnoreCase) || error.Contains("403", StringComparison.OrdinalIgnoreCase) ? StatusCode(StatusCodes.Status403Forbidden, ApiResponse<object>.Fail(error)) : BadRequest(ApiResponse<object>.Fail(error));
    }
}

