[Route("api/saude/export")]
public sealed class SaudeExportacaoController : SaudeApiControllerBase { private readonly ISaudeExportacaoService _s; public SaudeExportacaoController(ISaudeExportacaoService s)=>_s=s; [HttpGet("{recurso}.{formato}")] public async Task<IActionResult> Exportar(string recurso,string formato,CancellationToken ct){ var r=await _s.ExportarAsync(recurso,formato,ct).ConfigureAwait(false); if(r.IsFailure)return BadRequest(ApiResponse<object>.Fail(r.Error??"Falha na exportação.")); return File(r.Value??Array.Empty<byte>(), formato.Equals("json",StringComparison.OrdinalIgnoreCase)?"application/json":"text/csv", $"{recurso}.{formato}"); } }
